const retrieveDraftInvoices=()=>{

  let invoices = [];
  if (localStorage.getItem("draftInvoices")) {
    invoices = JSON.parse(localStorage.getItem("draftInvoices"));
    
  }
return invoices
}

const saveDraftInvoice = (invoiceDetails) => {
    let invoices = [];
    if (localStorage.getItem("draftInvoices")) {
      invoices = JSON.parse(localStorage.getItem("draftInvoices"));
    }
  
  
    let modifiedinvoices = [];
  
    if (invoices.length > 0) {
      const currentInvoices = [...invoices];
      if (currentInvoices.filter(x => x.invoice_number === invoiceDetails.invoice_number).length > 0) {
        console.log("Similar invoice already saved")
       
        return false
      } else {
        modifiedinvoices = [...currentInvoices, invoiceDetails];
       
      }
  
    } else {
      modifiedinvoices = [invoiceDetails];
    }
  
    localStorage.removeItem("draftInvoices");
    localStorage.setItem("draftInvoices", JSON.stringify(modifiedinvoices));
    return true;
  };


  const saveInvoiceItem = (invoice, invoice_item) => {
    let invoices = [];
    if (localStorage.getItem("draftInvoices")) {
      invoices = JSON.parse(localStorage.getItem("draftInvoices"));
    }
  
   
    const invoiceMinusThisOrder = invoices.filter(
      (x) => x.draft_id !== invoice.draft_id
    );
  
  
    const currentInvoiceItems = invoice.invoiceItems;
  
    let updatedInvoiceItems = [];
    if (currentInvoiceItems && currentInvoiceItems.length > 0) {
      const invoiceItemsMinusThisItem = currentInvoiceItems.filter(
        (x) => x.product !== invoice_item.product
      );
  
      updatedInvoiceItems = [...invoiceItemsMinusThisItem, invoice_item];
  
    } else {
      updatedInvoiceItems = [invoice_item];
    
    }
    invoice.invoiceItems = updatedInvoiceItems;
  
    let modifiedinvoices = [];
  
    modifiedinvoices = [...invoiceMinusThisOrder, invoice];
  
    localStorage.removeItem("draftInvoices");
    localStorage.setItem("draftInvoices", JSON.stringify(modifiedinvoices));
  
    return modifiedinvoices;
  };




  const deleteDraftInvoice = (draft_id) => {
    let modifiedInvoices = [];
    let invoices = [];
    if (localStorage.getItem("draftInvoices")) {
      invoices = JSON.parse(localStorage.getItem("draftInvoices"));
    }
  
    //Isolate current order
    const thisInvoice = invoices.find((x) => x.draft_id === draft_id);
  
    //Remove order from invoices list
    const invoicesMinusThisInvoice = invoices.filter((x) => x.draft_id !== draft_id);
  
  
    console.log("thisInvoice updated", thisInvoice);
    modifiedInvoices = [...invoicesMinusThisInvoice];
  
    localStorage.removeItem("draftInvoices");
    localStorage.setItem("draftInvoices", JSON.stringify(modifiedInvoices));
  
    return true;
  };

  export{
    saveDraftInvoice,
    saveInvoiceItem,
    retrieveDraftInvoices,
    deleteDraftInvoice
  }